<script setup lang="ts">import{ref}from'vue';import{api,type ApiError}from'../api';const message=ref('未签到');async function sign(){try{const id=localStorage.getItem('yk-attendance-id'),token=localStorage.getItem('yk-sign-token');if(!id||!token)throw{message:'暂无开放的签到'};await api(`/api/v1/attendance/${id}/sign?token=${encodeURIComponent(token)}`,{method:'POST'},'student');message.value='签到成功'}catch(e){message.value=(e as ApiError).message}}</script>
<template><div><div class="hero"><div><h1>课堂签到</h1><p>老师发布后，学生使用不可预测链接令牌完成签到。</p></div></div><section class="card" style="max-width:700px"><div class="row-between"><div><span class="badge">{{message}}</span><h2>RSA 数字签名课堂签到</h2></div><b>第 12 课时</b></div><button class="yk-button primary" style="width:100%" @click="sign">立即签到</button></section></div></template>
